<script setup>defineProps({rows:{type:Array,default:()=>[]},title:{type:String,default:'Split comparison'}})</script>
<template><section class="split-comparison"><header><span class="eyebrow">CONTEXT SPLITS</span><h2>{{title}}</h2></header><div v-if="rows.length"><article v-for="row in rows" :key="row.label"><span>{{row.label}}</span><strong>{{row.value ?? '—'}}</strong><i></i><small>{{row.comparison ?? '—'}}<em>{{row.context}}</em></small></article></div><p v-else>No valid split sample is currently available.</p></section></template>
